# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: gather
def gather(xs, factor=10):
    return [v * factor for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: sift
def sift(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return sift(intake(gather(emit(raw))))

